solution:
#include <stdio.h>

int main(void) {
    unsigned long tong = 0;
    for (int i = 0; i < 10; i++) {
        unsigned int tu;
        if (scanf("%x", &tu) != 1) return 1;
        if (i == 5) tu = 0;                 /* trường checksum được đặt bằng 0 */
        tong += tu;
    }
    while (tong >> 16) tong = (tong & 0xFFFF) + (tong >> 16);   /* cộng phần nhớ */
    printf("%04x\n", (unsigned int)(~tong & 0xFFFF));
    return 0;
}
